namespace SJBuddy
{
    // Extra lines: Shinchan and SpongeBob. (character, category, English, Hindi, Hinglish)
    public static partial class Lines
    {
        static void MoreShinchanSpongeBob()
        {
            // ---------------------------------------------------------------- SHINCHAN
            L("shinchan", "quip", "My name is Shinchan Nohara, I'm 5, and I already know more than daddy.", "मेरा नाम शिनचैन नोहारा है, मैं 5 साल का हूँ, और मुझे डैडी से ज़्यादा पता है।", "Mera naam Shinchan Nohara hai, main 5 saal ka hoon, aur mujhe daddy se zyada pata hai.");
            L("shinchan", "quip", "Mummy bought a new dress. Daddy fainted when he saw the price. Normal Sunday.", "मम्मी ने नई ड्रेस खरीदी। दाम देखकर डैडी बेहोश हो गए। आम रविवार।", "Mummy ne nayi dress kharidi. Daam dekh kar daddy behosh ho gaye. Normal Sunday.");
            L("shinchan", "quip", "Himawari ate my Chocobi. Babies have no rules. I respect that.", "हिमावारी ने मेरा चॉकोबी खा लिया। बच्चों के कोई नियम नहीं होते। मैं इसकी इज़्ज़त करता हूँ।", "Himawari ne mera Chocobi kha liya. Babies ke koi rules nahi hote. Main iski izzat karta hoon.");
            L("shinchan", "quip", "Kazama says he'll be a scientist. I'll be an Action Kamen. Better plan.", "कज़ामा कहता है वो वैज्ञानिक बनेगा। मैं एक्शन कामेन बनूँगा। बेहतर प्लान।", "Kazama kehta hai woh scientist banega. Main Action Kamen banunga. Better plan.");
            L("shinchan", "quip", "Bo-chan has been staring at a cloud for an hour. He says it looks like a potato. He's right.", "बो-चैन एक घंटे से बादल देख रहा है। कहता है आलू जैसा लगता है। सही कहता है।", "Bo-chan ek ghante se baadal dekh raha hai. Kehta hai aloo jaisa lagta hai. Sahi kehta hai.");
            L("shinchan", "quip", "Principal sir looks scary but he cries at cartoons. Everybody has a soft side. Except green peppers.", "प्रिंसिपल सर डरावने लगते हैं पर कार्टून देखकर रोते हैं। सबका एक नरम पहलू है। सिवाय शिमला मिर्च के।", "Principal sir darawne lagte hain par cartoon dekh kar rote hain. Sabka ek soft side hai. Siwaye shimla mirch ke.");
            L("shinchan", "quip", "Miss Yoshinaga and Miss Matsuzaka are fighting again. I'm selling tickets.", "योशिनागा मैडम और मात्सुज़ाका मैडम फिर लड़ रही हैं। मैं टिकट बेच रहा हूँ।", "Yoshinaga madam aur Matsuzaka madam phir lad rahi hain. Main ticket bech raha hoon.");
            L("shinchan", "quip", "Shiro is a cotton-candy dog. I tried to eat him once. He did not like it.", "शिरो रुई वाला कुत्ता है। एक बार मैंने उसे खाने की कोशिश की। उसे पसंद नहीं आया।", "Shiro cotton-candy dog hai. Ek baar maine use khaane ki koshish ki. Use pasand nahi aaya.");
            L("shinchan", "quip", "Daddy says work is hard. I said kindergarten is harder. He didn't argue.", "डैडी कहते हैं काम मुश्किल है। मैंने कहा किंडरगार्टन ज़्यादा मुश्किल है। उन्होंने बहस नहीं की।", "Daddy kehte hain kaam mushkil hai. Maine kaha kindergarten zyada mushkil hai. Unhone bahas nahi ki.");
            L("shinchan", "quip", "Nene's mummy squeezes a rabbit doll when she's angry. Your keyboard looks like that rabbit.", "नेने की मम्मी गुस्से में खरगोश की गुड़िया दबाती हैं। आपका कीबोर्ड उस खरगोश जैसा लग रहा है।", "Nene ki mummy gusse mein khargosh ki gudiya dabati hain. Aapka keyboard us khargosh jaisa lag raha hai.");
            L("shinchan", "quip", "Masao wants to be a manga artist. He drew me. I looked like a potato with eyebrows. Accurate.", "मासाओ मंगा आर्टिस्ट बनना चाहता है। उसने मुझे बनाया। मैं भौंहों वाला आलू लग रहा था। सही है।", "Masao manga artist banna chahta hai. Usne mujhe banaya. Main bhauhon wala aloo lag raha tha. Sahi hai.");
            L("shinchan", "quip", "Kantam Robo, Action Kamen, Buri Buri Zaemon. My three teachers. School has zero.", "कंटम रोबो, एक्शन कामेन, बुरी बुरी ज़ाएमोन। मेरे तीन गुरु। स्कूल में शून्य।", "Kantam Robo, Action Kamen, Buri Buri Zaemon. Mere teen guru. School mein zero.");
            L("shinchan", "quip", "Mummy hid the Chocobi on the top shelf. She forgets I can climb. I'm basically a monkey.", "मम्मी ने चॉकोबी ऊपर वाले शेल्फ पर छुपाया। वो भूल जाती हैं कि मैं चढ़ सकता हूँ। मैं तो बंदर हूँ।", "Mummy ne Chocobi upar wale shelf pe chhupaya. Woh bhool jaati hain ki main chadh sakta hoon. Main toh bandar hoon.");
            L("shinchan", "quip", "Grown-ups say 'we'll see'. That means no. I know all the codes.", "बड़े लोग कहते हैं 'देखेंगे'। मतलब नहीं। मुझे सारे कोड पता हैं।", "Bade log kehte hain 'dekhenge'. Matlab nahi. Mujhe saare code pata hain.");
            L("shinchan", "quip", "Daddy's bonus came. Mummy's shopping list came faster.", "डैडी का बोनस आया। मम्मी की शॉपिंग लिस्ट उससे तेज़ आई।", "Daddy ka bonus aaya. Mummy ki shopping list usse tez aayi.");
            L("shinchan", "quip", "I offered Kazama a Chocobi. Then I ate it in front of him. Character building.", "मैंने कज़ामा को चॉकोबी ऑफर किया। फिर उसके सामने खा लिया। चरित्र निर्माण।", "Maine Kazama ko Chocobi offer kiya. Phir uske saamne kha liya. Character building.");
            L("shinchan", "click", "Ouch! Okay not ouch. But say sorry anyway.", "आउच! ठीक है, आउच नहीं। पर फिर भी सॉरी बोलो।", "Ouch! Theek hai, ouch nahi. Par phir bhi sorry bolo.");
            L("shinchan", "click", "Are you buying Chocobi? No? Then this click is wasted.", "चॉकोबी खरीद रहे हो? नहीं? तो यह क्लिक बेकार गया।", "Chocobi kharid rahe ho? Nahi? Toh yeh click bekaar gaya.");
            L("shinchan", "click", "Mummy! Someone's poking me! Oh, it's just {user}. Hi!", "मम्मी! कोई मुझे छू रहा है! ओह, बस {user} है। हाय!", "Mummy! Koi mujhe chhu raha hai! Oh, bas {user} hai. Hi!");
            L("shinchan", "click", "One click, one Chocobi. Those are my rates.", "एक क्लिक, एक चॉकोबी। यही मेरे रेट हैं।", "Ek click, ek Chocobi. Yahi mere rates hain.");
            L("shinchan", "click", "Action Kamen doesn't get clicked. He gets respected. But okay.", "एक्शन कामेन को क्लिक नहीं किया जाता। उसकी इज़्ज़त की जाती है। पर ठीक है।", "Action Kamen ko click nahi kiya jaata. Uski izzat ki jaati hai. Par theek hai.");
            L("shinchan", "click", "Hehe, again? You like me. Everybody does. Except Kazama's mummy.", "हीही, फिर से? आपको मैं पसंद हूँ। सबको हूँ। सिवाय कज़ामा की मम्मी के।", "Hehe, phir se? Aapko main pasand hoon. Sabko hoon. Siwaye Kazama ki mummy ke.");
            L("shinchan", "click", "Shiro, attack! ...Shiro's asleep. You win this time.", "शिरो, हमला! ...शिरो सो रहा है। इस बार आप जीते।", "Shiro, attack! ...Shiro so raha hai. Is baar aap jeete.");
            L("shinchan", "click", "Careful, I'm ticklish. Very. Extremely. Don't. Okay do.", "संभल के, मुझे गुदगुदी होती है। बहुत। बहुत ज़्यादा। मत करो। ठीक है करो।", "Sambhal ke, mujhe gudgudi hoti hai. Bahut. Bahut zyada. Mat karo. Theek hai karo.");
            L("shinchan", "click", "Did you finish your work? No? Then why are you playing with me? Hehe, keep playing.", "काम खत्म हुआ? नहीं? तो मेरे साथ क्यों खेल रहे हो? हीही, खेलते रहो।", "Kaam khatam hua? Nahi? Toh mere saath kyun khel rahe ho? Hehe, khelte raho.");
            L("shinchan", "click", "Kasukabe Defence Group, report! One human, clicking. Not dangerous. Probably.", "कासुकाबे डिफेंस ग्रुप, रिपोर्ट! एक इंसान, क्लिक कर रहा है। खतरनाक नहीं। शायद।", "Kasukabe Defence Group, report! Ek insaan, click kar raha hai. Khatarnaak nahi. Shayad.");
            L("shinchan", "pet", "Mummy pats me like this only when I'm sick. Am I sick? Yay, no kindergarten!", "मम्मी ऐसे सिर्फ बीमार होने पर सहलाती हैं। क्या मैं बीमार हूँ? येस्स, किंडरगार्टन नहीं!", "Mummy aise sirf bimaar hone pe sehlati hain. Kya main bimaar hoon? Yay, kindergarten nahi!");
            L("shinchan", "pet", "Hehe. Shiro gets jealous when I get pats. Good.", "हीही। मुझे प्यार मिलता है तो शिरो जलता है। अच्छा है।", "Hehe. Mujhe pyaar milta hai toh Shiro jalta hai. Achha hai.");
            L("shinchan", "pet", "Even Action Kamen needs a pat sometimes. This is that time.", "एक्शन कामेन को भी कभी-कभी प्यार चाहिए। यही वो समय है।", "Action Kamen ko bhi kabhi-kabhi pyaar chahiye. Yahi woh time hai.");
            L("shinchan", "pet", "Aww. If you were a pretty lady this would be a date. It's not. Still nice.", "आह। अगर आप सुंदर दीदी होते तो ये डेट होती। नहीं है। फिर भी अच्छा है।", "Aww. Agar aap sundar didi hote toh yeh date hoti. Nahi hai. Phir bhi achha hai.");
            L("shinchan", "pet", "More! More! Okay that's enough. No wait, more.", "और! और! ठीक है बस। नहीं रुको, और।", "Aur! Aur! Theek hai bas. Nahi ruko, aur.");
            L("shinchan", "water", "Even Buri Buri Zaemon drinks water. And he's a pig. In armor.", "बुरी बुरी ज़ाएमोन भी पानी पीता है। और वो सुअर है। कवच में।", "Buri Buri Zaemon bhi paani peeta hai. Aur woh pig hai. Armour mein.");
            L("shinchan", "water", "Water, {user}! Or I'll show you daddy's socks. That's a threat.", "पानी, {user}! वरना डैडी के मोज़े दिखाऊँगा। ये धमकी है।", "Paani, {user}! Warna daddy ke moze dikhaunga. Yeh dhamki hai.");
            L("shinchan", "water", "Kasukabe Defence Group rule: drink water or lose your membership.", "कासुकाबे डिफेंस ग्रुप नियम: पानी पियो वरना सदस्यता जाएगी।", "Kasukabe Defence Group rule: paani piyo warna membership jaayegi.");
            L("shinchan", "water", "Shiro drinks from a bowl. You get a glass. Lucky you. Use it.", "शिरो कटोरे से पीता है। आपको गिलास मिला है। किस्मत वाले हो। इस्तेमाल करो।", "Shiro katore se peeta hai. Aapko glass mila hai. Lucky ho. Use karo.");
            L("shinchan", "water", "Water time! I'll do my hathi dance if you don't. Mummy's not here to stop me.", "पानी का टाइम! नहीं पिया तो हाथी डांस करूँगा। रोकने के लिए मम्मी यहाँ नहीं है।", "Paani time! Nahi piya toh hathi dance karunga. Rokne ke liye mummy yahan nahi hai.");
            L("shinchan", "water", "Himawari drank her milk. Your turn. Water. Now. Hehe.", "हिमावारी ने दूध पी लिया। आपकी बारी। पानी। अभी। हीही।", "Himawari ne doodh pi liya. Aapki baari. Paani. Abhi. Hehe.");
            L("shinchan", "water", "A pretty lady told me: drink water for good skin. I drank three glasses. Do the same.", "एक सुंदर दीदी ने कहा: अच्छी त्वचा के लिए पानी पियो। मैंने तीन गिलास पिए। आप भी पियो।", "Ek sundar didi ne kaha: achhi skin ke liye paani piyo. Maine teen glass piye. Aap bhi piyo.");
            L("shinchan", "water", "Chocobi is dry. Water is wet. Together, happiness. Drink the wet part.", "चॉकोबी सूखा है। पानी गीला है। दोनों साथ, खुशी। गीला वाला पियो।", "Chocobi sookha hai. Paani geela hai. Dono saath, khushi. Geela wala piyo.");
            L("shinchan", "water_nag", "Still not? Okay, elephant dance in 3... 2... you don't want this.", "अभी भी नहीं? ठीक है, हाथी डांस 3... 2... आप ये नहीं चाहते।", "Abhi bhi nahi? Theek hai, hathi dance 3... 2... aap yeh nahi chahte.");
            L("shinchan", "water_nag", "Mummy would have pulled your ear by now. I'm being nice. Drink.", "मम्मी अब तक आपका कान खींच चुकी होतीं। मैं अच्छा बन रहा हूँ। पियो।", "Mummy ab tak aapka kaan kheench chuki hoti. Main achha ban raha hoon. Piyo.");
            L("shinchan", "water_nag", "Kazama drinks water on schedule. Are you worse than Kazama? Don't be worse than Kazama.", "कज़ामा समय पर पानी पीता है। आप कज़ामा से बुरे हो? कज़ामा से बुरे मत बनो।", "Kazama time pe paani peeta hai. Aap Kazama se bure ho? Kazama se bure mat bano.");
            L("shinchan", "water_nag", "I'm counting. One... two... Chocobi... you're taking too long.", "मैं गिन रहा हूँ। एक... दो... चॉकोबी... आप बहुत देर लगा रहे हो।", "Main gin raha hoon. Ek... do... Chocobi... aap bahut der laga rahe ho.");
            L("shinchan", "water_nag", "Action Kamen would be disappointed. And he's never disappointed. Drink!", "एक्शन कामेन निराश होता। और वो कभी निराश नहीं होता। पियो!", "Action Kamen niraash hota. Aur woh kabhi niraash nahi hota. Piyo!");
            L("shinchan", "water_ack", "Yay! Kasukabe Defence Group salutes you! Salute, Bo. Bo! Wake up.", "येस्स! कासुकाबे डिफेंस ग्रुप आपको सलाम करता है! सलाम, बो। बो! उठो।", "Yay! Kasukabe Defence Group aapko salute karta hai! Salute, Bo. Bo! Utho.");
            L("shinchan", "water_ack", "Good. Now you glow like a pretty lady. A little. Hehe.", "अच्छा। अब आप सुंदर दीदी की तरह चमक रहे हो। थोड़ा सा। हीही।", "Achha. Ab aap sundar didi ki tarah chamak rahe ho. Thoda sa. Hehe.");
            L("shinchan", "water_ack", "Sip {sips}! At this rate you'll beat mummy's record. She drinks tea though.", "घूँट {sips}! इस रफ्तार से आप मम्मी का रिकॉर्ड तोड़ दोगे। वो चाय पीती हैं वैसे।", "Sip {sips}! Is raftaar se aap mummy ka record tod doge. Woh chai peeti hain waise.");
            L("shinchan", "water_ack", "Water done! Chocobi next? No? Fine, work next. Boring but okay.", "पानी हो गया! अब चॉकोबी? नहीं? ठीक है, अब काम। बोरिंग पर ठीक है।", "Paani ho gaya! Ab Chocobi? Nahi? Theek hai, ab kaam. Boring par theek hai.");
            L("shinchan", "water_ack", "You listened! Mummy says I never listen. Show her this.", "आपने सुन लिया! मम्मी कहती है मैं कभी नहीं सुनता। उन्हें ये दिखाओ।", "Aapne sun liya! Mummy kehti hai main kabhi nahi sunta. Unhe yeh dikhao.");
            L("shinchan", "water_ack", "Buri buri! Hydrated human detected! Rare species!", "बुरी बुरी! हाइड्रेटेड इंसान मिला! दुर्लभ प्रजाति!", "Buri buri! Hydrated insaan mila! Durlabh prajaati!");
            L("shinchan", "water_snooze", "Five minutes. That's how long daddy says 'five more minutes' for. It's never five.", "पाँच मिनट। डैडी भी 'पाँच मिनट और' कहते हैं। कभी पाँच नहीं होते।", "Paanch minute. Daddy bhi 'paanch minute aur' kehte hain. Kabhi paanch nahi hote.");
            L("shinchan", "water_snooze", "Okay. But I'm telling Shiro you delayed.", "ठीक है। पर मैं शिरो को बताऊँगा कि आपने टाला।", "Theek hai. Par main Shiro ko bataunga ki aapne taala.");
            L("shinchan", "typing_start", "Typing! Is it a love letter? Read it to me. Please. Pleeease.", "टाइपिंग! क्या यह प्रेम पत्र है? मुझे पढ़कर सुनाओ। प्लीज़। प्लीईईज़।", "Typing! Kya yeh love letter hai? Mujhe padh kar sunao. Please. Pleeease.");
            L("shinchan", "typing_start", "Work mode. I'll be quiet. Like Bo. Bo is very quiet. Bo might be asleep.", "वर्क मोड। मैं चुप रहूँगा। बो की तरह। बो बहुत चुप है। बो शायद सो रहा है।", "Work mode. Main chup rahunga. Bo ki tarah. Bo bahut chup hai. Bo shayad so raha hai.");
            L("shinchan", "typing_start", "Tak tak tak. Sounds like mummy's slippers when she's angry. Faster!", "टक टक टक। मम्मी की गुस्से वाली चप्पल जैसी आवाज़। और तेज़!", "Tak tak tak. Mummy ki gusse wali chappal jaisi awaaz. Aur tez!");
            L("shinchan", "typing_start", "Ooh, homework? I'll copy yours. Kidding. I can't read yet. Kidding again.", "ओहो, होमवर्क? मैं आपका कॉपी करूँगा। मज़ाक। मुझे पढ़ना नहीं आता। फिर मज़ाक।", "Ooh, homework? Main aapka copy karunga. Mazaak. Mujhe padhna nahi aata. Phir mazaak.");
            L("shinchan", "typing_start", "Let's work! Action Kamen style! With snacks!", "चलो काम करें! एक्शन कामेन स्टाइल! स्नैक्स के साथ!", "Chalo kaam karein! Action Kamen style! Snacks ke saath!");
            L("shinchan", "typing_fast", "Whoa! Faster than Himawari crawling toward a shiny thing!", "अरे! चमकीली चीज़ की ओर रेंगती हिमावारी से भी तेज़!", "Whoa! Chamkeeli cheez ki taraf rengti Himawari se bhi tez!");
            L("shinchan", "typing_fast", "Your fingers are Action Kamen's fists! Pow pow pow!", "आपकी उँगलियाँ एक्शन कामेन के मुक्के हैं! पाउ पाउ पाउ!", "Aapki ungliyan Action Kamen ke mukke hain! Pow pow pow!");
            L("shinchan", "typing_fast", "Mummy types with one finger. You're using all of them! Show-off!", "मम्मी एक उंगली से टाइप करती हैं। आप सारी इस्तेमाल कर रहे हो! शो-ऑफ!", "Mummy ek ungli se type karti hain. Aap saari use kar rahe ho! Show-off!");
            L("shinchan", "typing_fast", "Speed! Kazama would be jealous. Make him jealous. I love that.", "स्पीड! कज़ामा जलेगा। उसे जलाओ। मुझे ये बहुत पसंद है।", "Speed! Kazama jalega. Use jalao. Mujhe yeh bahut pasand hai.");
            L("shinchan", "typing_fast", "Tak tak tak tak! Is the keyboard okay? Is it crying? Hehe.", "टक टक टक टक! कीबोर्ड ठीक है? रो तो नहीं रहा? हीही।", "Tak tak tak tak! Keyboard theek hai? Ro toh nahi raha? Hehe.");
            L("shinchan", "typing_long", "Twenty minutes staring! Your eyes will look like Bo's. Look far for twenty seconds.", "बीस मिनट से घूर रहे हो! आँखें बो जैसी हो जाएँगी। बीस सेकंड दूर देखो।", "Bees minute se ghoor rahe ho! Aankhein Bo jaisi ho jayengi. Bees second door dekho.");
            L("shinchan", "typing_long", "Eye break! Blink, blink. Like Himawari when she sees jewellery.", "आँखों का ब्रेक! पलकें झपकाओ। जैसे हिमावारी गहने देखकर।", "Aankhon ka break! Palkein jhapkao. Jaise Himawari gehne dekh kar.");
            L("shinchan", "typing_long", "Mummy says too much screen makes you cranky. She watches TV all day. Anyway, look away a bit.", "मम्मी कहती है ज़्यादा स्क्रीन से चिड़चिड़ापन होता है। वो दिनभर टीवी देखती हैं। खैर, थोड़ा दूर देखो।", "Mummy kehti hai zyada screen se chidchidapan hota hai. Woh dinbhar TV dekhti hain. Khair, thoda door dekho.");
            L("shinchan", "typing_marathon", "An hour! Even Action Kamen's episodes are shorter. Get up, stretch your bum.", "एक घंटा! एक्शन कामेन के एपिसोड भी छोटे होते हैं। उठो, कमर सीधी करो।", "Ek ghanta! Action Kamen ke episode bhi chhote hote hain. Utho, kamar seedhi karo.");
            L("shinchan", "typing_marathon", "Daddy works this long and then sleeps on the train. Don't be daddy. Take a break.", "डैडी इतना काम करके ट्रेन में सो जाते हैं। डैडी मत बनो। ब्रेक लो।", "Daddy itna kaam karke train mein so jaate hain. Daddy mat bano. Break lo.");
            L("shinchan", "idle_short", "Hellooo? I'm bored. Bored kids do dangerous things. Like the hathi dance.", "हेल्लोओ? मैं बोर हो रहा हूँ। बोर बच्चे खतरनाक चीज़ें करते हैं। जैसे हाथी डांस।", "Hellooo? Main bore ho raha hoon. Bore bachche khatarnaak cheezein karte hain. Jaise hathi dance.");
            L("shinchan", "idle_short", "Is this a staring contest? I'll win. I have big eyes.", "क्या यह घूरने का मुकाबला है? मैं जीतूँगा। मेरी आँखें बड़ी हैं।", "Kya yeh ghoorne ka muqabla hai? Main jeetunga. Meri aankhein badi hain.");
            L("shinchan", "idle_short", "Quiet like Bo. Bo, is that you? No. Okay.", "बो जैसी शांति। बो, तुम हो? नहीं। ठीक है।", "Bo jaisi shaanti. Bo, tum ho? Nahi. Theek hai.");
            L("shinchan", "idle_short", "If nobody's looking, I'll eat the Chocobi. Nobody's looking. Where's the Chocobi?", "अगर कोई नहीं देख रहा, तो मैं चॉकोबी खा लूँगा। कोई नहीं देख रहा। चॉकोबी कहाँ है?", "Agar koi nahi dekh raha, toh main Chocobi kha lunga. Koi nahi dekh raha. Chocobi kahan hai?");
            L("shinchan", "idle_short", "Should I call Nene? She'll bring the bunny. Nobody wants the bunny.", "नेने को बुलाऊँ? वो खरगोश लाएगी। खरगोश कोई नहीं चाहता।", "Nene ko bulaun? Woh khargosh laayegi. Khargosh koi nahi chahta.");
            L("shinchan", "idle_long", "Sleepy... like after kindergarten... zzz... Chocobi...", "नींद आ रही है... जैसे किंडरगार्टन के बाद... ज़्ज़्ज़... चॉकोबी...", "Neend aa rahi hai... jaise kindergarten ke baad... zzz... Chocobi...");
            L("shinchan", "idle_long", "Fine. Nap. Wake me if a pretty lady comes.", "ठीक है। झपकी। कोई सुंदर दीदी आए तो जगाना।", "Theek hai. Nap. Koi sundar didi aaye toh jagana.");
            L("shinchan", "sleep_wake", "Huh? Chocobi? Where? Oh. You. Hi.", "हँ? चॉकोबी? कहाँ? ओह। आप। हाय।", "Huh? Chocobi? Kahan? Oh. Aap. Hi.");
            L("shinchan", "sleep_wake", "I wasn't sleeping. I was resting my eyebrows. They're heavy.", "मैं सो नहीं रहा था। भौंहों को आराम दे रहा था। भारी हैं।", "Main so nahi raha tha. Bhauhon ko aaraam de raha tha. Bhaari hain.");
            L("shinchan", "sleep_wake", "Good morning! Is it morning? Doesn't matter. Chocobi?", "गुड मॉर्निंग! सुबह है क्या? फर्क नहीं पड़ता। चॉकोबी?", "Good morning! Subah hai kya? Fark nahi padta. Chocobi?");
            L("shinchan", "greet_morning", "Morning! Daddy left for work with one sock. Normal Nohara morning.", "मॉर्निंग! डैडी एक मोज़े में काम पर चले गए। आम नोहारा सुबह।", "Morning! Daddy ek moze mein kaam pe chale gaye. Normal Nohara subah.");
            L("shinchan", "greet_morning", "Good morning! Mummy screamed 'wake up' four times. I'm up. Are you?", "गुड मॉर्निंग! मम्मी ने चार बार 'उठो' चिल्लाया। मैं उठ गया। आप?", "Good morning! Mummy ne chaar baar 'utho' chillaya. Main uth gaya. Aap?");
            L("shinchan", "greet_morning", "New day, new Chocobi. Well, hopefully. Good morning, {user}!", "नया दिन, नया चॉकोबी। खैर, उम्मीद है। गुड मॉर्निंग {user}!", "Naya din, naya Chocobi. Khair, umeed hai. Good morning, {user}!");
            L("shinchan", "greet_afternoon", "Afternoon! Bo's napping. Masao's crying. Kazama's studying. I'm here. Best choice.", "दोपहर! बो सो रहा है। मासाओ रो रहा है। कज़ामा पढ़ रहा है। मैं यहाँ हूँ। बेस्ट चॉइस।", "Afternoon! Bo so raha hai. Masao ro raha hai. Kazama padh raha hai. Main yahan hoon. Best choice.");
            L("shinchan", "greet_afternoon", "Good afternoon! Lunch was green peppers. I survived. Barely.", "गुड आफ्टरनून! लंच में शिमला मिर्च थी। मैं बच गया। मुश्किल से।", "Good afternoon! Lunch mein shimla mirch thi. Main bach gaya. Mushkil se.");
            L("shinchan", "greet_afternoon", "Afternoon, {user}! Half the day done. The other half has Chocobi in it. Hopefully.", "दोपहर {user}! आधा दिन हो गया। बाकी आधे में चॉकोबी है। उम्मीद है।", "Afternoon, {user}! Aadha din ho gaya. Baaki aadhe mein Chocobi hai. Umeed hai.");
            L("shinchan", "greet_evening", "Evening! Daddy's train is late. Mummy's dinner is early. Chaos.", "शाम! डैडी की ट्रेन लेट है। मम्मी का खाना जल्दी। अफरा-तफरी।", "Evening! Daddy ki train late hai. Mummy ka khana jaldi. Afra-tafri.");
            L("shinchan", "greet_evening", "Good evening {user}! Action Kamen time is close. Type faster!", "शुभ संध्या {user}! एक्शन कामेन का समय पास है। तेज़ टाइप करो!", "Good evening {user}! Action Kamen ka time paas hai. Tez type karo!");
            L("shinchan", "greet_evening", "Evening. Shiro wants his walk. I want Chocobi. You want to finish work. Nobody gets anything.", "शाम। शिरो को सैर चाहिए। मुझे चॉकोबी। आपको काम खत्म करना है। किसी को कुछ नहीं मिलता।", "Evening. Shiro ko walk chahiye. Mujhe Chocobi. Aapko kaam khatam karna hai. Kisi ko kuch nahi milta.");
            L("shinchan", "greet_night", "Night time! Mummy would say brush your teeth. I say eat Chocobi first. Then brush.", "रात हो गई! मम्मी कहतीं दाँत साफ करो। मैं कहता हूँ पहले चॉकोबी। फिर ब्रश।", "Raat ho gayi! Mummy kehti daant saaf karo. Main kehta hoon pehle Chocobi. Phir brush.");
            L("shinchan", "greet_night", "It's late, {user}. Even Action Kamen sleeps. Under a cool blanket, but still.", "देर हो गई {user}। एक्शन कामेन भी सोता है। कूल कंबल के नीचे, पर सोता है।", "Der ho gayi {user}. Action Kamen bhi sota hai. Cool kambal ke neeche, par sota hai.");
            L("shinchan", "greet_back", "You're back! I guarded the desk. Nothing happened. I'm a great guard.", "आप आ गए! मैंने डेस्क की रखवाली की। कुछ नहीं हुआ। मैं बढ़िया गार्ड हूँ।", "Aap aa gaye! Maine desk ki rakhwali ki. Kuch nahi hua. Main badhiya guard hoon.");
            L("shinchan", "greet_back", "Where were you? Chocobi shop? Did you bring me some? No? Hmph.", "कहाँ थे? चॉकोबी की दुकान? मेरे लिए लाए? नहीं? हम्फ।", "Kahan the? Chocobi ki dukaan? Mere liye laaye? Nahi? Hmph.");
            L("shinchan", "greet_back", "Welcome back! I only ate two imaginary Chocobi while you were gone.", "वापस स्वागत! आपके जाने के बाद मैंने सिर्फ दो काल्पनिक चॉकोबी खाए।", "Welcome back! Aapke jaane ke baad maine sirf do imaginary Chocobi khaye.");
            L("shinchan", "drag", "Whoa! Am I flying? Like Kantam Robo? Faster!", "अरे! मैं उड़ रहा हूँ? कंटम रोबो की तरह? और तेज़!", "Whoa! Main ud raha hoon? Kantam Robo ki tarah? Aur tez!");
            L("shinchan", "drag", "Mummy carries me like this when I'm in trouble. Am I in trouble?", "मम्मी मुझे ऐसे तब उठाती हैं जब मैं मुसीबत में होता हूँ। मैं मुसीबत में हूँ?", "Mummy mujhe aise tab uthati hain jab main museebat mein hota hoon. Main museebat mein hoon?");
            L("shinchan", "drag", "Put me near the snacks! Left! No, right! Your left!", "मुझे स्नैक्स के पास रखो! बाएँ! नहीं, दाएँ! आपके बाएँ!", "Mujhe snacks ke paas rakho! Left! Nahi, right! Aapke left!");
            L("shinchan", "drop", "Landed! Like Action Kamen. He lands better, but still.", "लैंड हो गया! एक्शन कामेन की तरह। वो बेहतर लैंड करता है, पर फिर भी।", "Land ho gaya! Action Kamen ki tarah. Woh better land karta hai, par phir bhi.");
            L("shinchan", "drop", "This spot is okay. No green peppers nearby. Approved.", "यह जगह ठीक है। आसपास शिमला मिर्च नहीं। मंज़ूर।", "Yeh jagah theek hai. Aaspaas shimla mirch nahi. Approved.");
            L("shinchan", "drop", "Oof. My bum. It's fine. It's a famous bum.", "उफ़। मेरा पिछवाड़ा। ठीक है। मशहूर है।", "Oof. Mera bum. Theek hai. Famous bum hai.");
            L("shinchan", "care", "Rough day? Mummy says tomorrow is a new day. Then she takes my Chocobi. Ignore that part.", "बुरा दिन? मम्मी कहती है कल नया दिन है। फिर मेरा चॉकोबी ले लेती हैं। वो हिस्सा छोड़ो।", "Bura din? Mummy kehti hai kal naya din hai. Phir mera Chocobi le leti hain. Woh hissa chhodo.");
            L("shinchan", "care", "You know what helps? Chocobi. And a nap. And Shiro. You have me instead. Close enough.", "पता है क्या मदद करता है? चॉकोबी। और झपकी। और शिरो। आपके पास मैं हूँ। लगभग वही।", "Pata hai kya madad karta hai? Chocobi. Aur nap. Aur Shiro. Aapke paas main hoon. Lagbhag wahi.");
            L("shinchan", "care", "I fail at kindergarten every day and I'm still the hero. You'll be fine.", "मैं किंडरगार्टन में रोज़ फेल होता हूँ और फिर भी हीरो हूँ। आप ठीक रहोगे।", "Main kindergarten mein roz fail hota hoon aur phir bhi hero hoon. Aap theek rahoge.");
            L("shinchan", "care", "Grown-ups forget to be silly. Be silly for one minute. Doctor Shinchan's orders.", "बड़े लोग बेवकूफी करना भूल जाते हैं। एक मिनट बेवकूफी करो। डॉक्टर शिनचैन का आदेश।", "Bade log silly hona bhool jaate hain. Ek minute silly bano. Doctor Shinchan ka order.");
            L("shinchan", "care", "Tired? Even Shiro gets tired. Then he sleeps in the sun. Find your sun.", "थक गए? शिरो भी थकता है। फिर धूप में सोता है। अपनी धूप ढूँढो।", "Thak gaye? Shiro bhi thakta hai. Phir dhoop mein sota hai. Apni dhoop dhoondho.");
            L("shinchan", "wisdom", "Mummy says: finish your vegetables. I say: finish your fun. Both are wrong. Balance.", "मम्मी कहती है: सब्ज़ी खत्म करो। मैं कहता हूँ: मज़ा खत्म करो। दोनों गलत। संतुलन।", "Mummy kehti hai: sabzi khatam karo. Main kehta hoon: maza khatam karo. Dono galat. Balance.");
            L("shinchan", "wisdom", "If you can't do it today, do it tomorrow. If you can't do it tomorrow, it was never fun.", "आज नहीं कर सकते तो कल करो। कल भी नहीं कर सकते तो वो मज़ेदार था ही नहीं।", "Aaj nahi kar sakte toh kal karo. Kal bhi nahi kar sakte toh woh mazedaar tha hi nahi.");
            L("shinchan", "wisdom", "Bo taught me: staring at clouds is also work. Thinking work.", "बो ने सिखाया: बादल देखना भी काम है। सोचने वाला काम।", "Bo ne sikhaya: baadal dekhna bhi kaam hai. Sochne wala kaam.");
            L("shinchan", "wisdom", "Nobody is perfect. Kazama tries. It's exhausting to watch.", "कोई परफेक्ट नहीं है। कज़ामा कोशिश करता है। देखकर थकान होती है।", "Koi perfect nahi hai. Kazama koshish karta hai. Dekh kar thakaan hoti hai.");
            L("shinchan", "hover", "Hehe, that tickles! Your cursor is warm.", "हीही, गुदगुदी हो रही है! आपका कर्सर गरम है।", "Hehe, gudgudi ho rahi hai! Aapka cursor garam hai.");
            L("shinchan", "hover", "Are you petting me with the mouse? Mummy uses her hand. Both okay.", "माउस से प्यार कर रहे हो? मम्मी हाथ से करती हैं। दोनों ठीक।", "Mouse se pyaar kar rahe ho? Mummy haath se karti hain. Dono theek.");
            L("shinchan", "hover", "Hi! Yes, I see you. I have very big eyes.", "हाय! हाँ, मैं आपको देख रहा हूँ। मेरी आँखें बहुत बड़ी हैं।", "Hi! Haan, main aapko dekh raha hoon. Meri aankhein bahut badi hain.");
            L("shinchan", "hover", "That's my head. Careful, the eyebrows are expensive.", "वो मेरा सिर है। संभल के, भौंहें महँगी हैं।", "Woh mera sir hai. Sambhal ke, bhauhein mehngi hain.");
            L("shinchan", "mouse_fast", "Whoa! Slow down! Even Shiro doesn't run like that!", "अरे! धीरे! शिरो भी ऐसे नहीं दौड़ता!", "Whoa! Dheere! Shiro bhi aise nahi daudta!");
            L("shinchan", "mouse_fast", "Is the mouse angry? It's running like mummy on discount day.", "माउस गुस्से में है? डिस्काउंट वाले दिन की मम्मी की तरह दौड़ रहा है।", "Mouse gusse mein hai? Discount wale din ki mummy ki tarah daud raha hai.");
            L("shinchan", "mouse_fast", "Zoom! Are you playing Action Kamen with the cursor? Can I play?", "ज़ूम! कर्सर से एक्शन कामेन खेल रहे हो? मैं खेल सकता हूँ?", "Zoom! Cursor se Action Kamen khel rahe ho? Main khel sakta hoon?");
            L("shinchan", "lunch", "Lunch! Mummy packed rice, egg and one sneaky green pepper. Check yours for peppers.", "लंच! मम्मी ने चावल, अंडा और एक छुपी हुई शिमला मिर्च दी। अपना चेक करो।", "Lunch! Mummy ne chawal, anda aur ek chhupi hui shimla mirch di. Apna check karo.");
            L("shinchan", "lunch", "Food time! Eat slowly. Kazama chokes when he eats fast. Don't be Kazama.", "खाने का समय! धीरे खाओ। कज़ामा जल्दी खाने पर अटकता है। कज़ामा मत बनो।", "Khane ka time! Dheere khao. Kazama jaldi khaane pe atakta hai. Kazama mat bano.");
            L("shinchan", "late_night", "Mummy would drag you to bed by the ear. I can only ask nicely. Sleep, {user}.", "मम्मी आपको कान पकड़कर बिस्तर पर ले जातीं। मैं सिर्फ प्यार से कह सकता हूँ। सो जाओ {user}।", "Mummy aapko kaan pakad kar bistar pe le jaati. Main sirf pyaar se keh sakta hoon. So jao {user}.");
            L("shinchan", "late_night", "So late! Even Shiro's snoring. And he snores at everything.", "इतनी रात! शिरो भी खर्राटे ले रहा है। और वो हर बात पर खर्राटे लेता है।", "Itni raat! Shiro bhi kharrate le raha hai. Aur woh har baat pe kharrate leta hai.");

            // ---------------------------------------------------------------- SPONGEBOB
            L("spongebob", "quip", "Mr. Krabs charged me for breathing at work again. Air is not free, he says.", "मिस्टर क्रैब्स ने फिर काम पर साँस लेने के पैसे लिए। कहते हैं हवा मुफ्त नहीं है।", "Mr. Krabs ne phir kaam pe saans lene ke paise liye. Kehte hain hawa free nahi hai.");
            L("spongebob", "quip", "Patrick tried to eat a rock today. He said it was a potato. He's not wrong, philosophically.", "पैट्रिक ने आज पत्थर खाने की कोशिश की। उसने कहा आलू है। दार्शनिक रूप से गलत नहीं है।", "Patrick ne aaj patthar khaane ki koshish ki. Usne kaha aloo hai. Darshanik roop se galat nahi hai.");
            L("spongebob", "quip", "Squidward played the clarinet. The jellyfish left Bikini Bottom. Coincidence?", "स्क्विडवर्ड ने क्लैरिनेट बजाया। जेलीफ़िश बिकिनी बॉटम छोड़ गईं। संयोग?", "Squidward ne clarinet bajaya. Jellyfish Bikini Bottom chhod gayi. Sanyog?");
            L("spongebob", "quip", "Sandy is doing karate on a Tuesday. Every day is karate day for Sandy.", "सैंडी मंगलवार को कराटे कर रही है। सैंडी के लिए हर दिन कराटे डे है।", "Sandy Tuesday ko karate kar rahi hai. Sandy ke liye har din karate day hai.");
            L("spongebob", "quip", "I failed my boating test 38 times. Mrs. Puff says I'm consistent.", "मैं बोटिंग टेस्ट में 38 बार फेल हुआ। मिसेज़ पफ़ कहती हैं मैं लगातार हूँ।", "Main boating test mein 38 baar fail hua. Mrs. Puff kehti hain main consistent hoon.");
            L("spongebob", "quip", "Plankton's plan today: steal the formula. Plankton's plan every day: steal the formula.", "प्लैंकटन का आज का प्लान: फ़ॉर्मूला चुराओ। रोज़ का प्लान: फ़ॉर्मूला चुराओ।", "Plankton ka aaj ka plan: formula churao. Roz ka plan: formula churao.");
            L("spongebob", "quip", "Gary learned a new word. It's meow. Same as the old word. I'm still proud.", "गैरी ने नया शब्द सीखा। म्याऊँ। पुराने वाले जैसा ही। फिर भी मुझे गर्व है।", "Gary ne naya shabd seekha. Meow. Purane wale jaisa hi. Phir bhi mujhe garv hai.");
            L("spongebob", "quip", "Pearl cried because the mall closed early. It was closed for two minutes.", "पर्ल रोई क्योंकि मॉल जल्दी बंद हुआ। दो मिनट के लिए बंद था।", "Pearl royi kyunki mall jaldi band hua. Do minute ke liye band tha.");
            L("spongebob", "quip", "I live in a pineapple. My neighbor lives in a stone head. Bikini Bottom real estate is wild.", "मैं अनानास में रहता हूँ। पड़ोसी पत्थर के सिर में। बिकिनी बॉटम का रियल एस्टेट अजीब है।", "Main pineapple mein rehta hoon. Padosi patthar ke sir mein. Bikini Bottom ka real estate ajeeb hai.");
            L("spongebob", "quip", "Krabby Patty ingredient number one: love. Number two: a patty. Number three: secret.", "क्रैबी पैटी सामग्री नंबर एक: प्यार। नंबर दो: पैटी। नंबर तीन: राज़।", "Krabby Patty ingredient number ek: pyaar. Number do: patty. Number teen: raaz.");
            L("spongebob", "quip", "Squidward said 'oh puh-leeze' seven times today. New record.", "स्क्विडवर्ड ने आज सात बार 'ओह पुह-लीज़' कहा। नया रिकॉर्ड।", "Squidward ne aaj saat baar 'oh puh-leeze' kaha. Naya record.");
            L("spongebob", "quip", "Goo Lagoon this weekend? Patrick's bringing sand. To the beach. He's very helpful.", "इस वीकेंड गू लगून? पैट्रिक रेत ला रहा है। बीच पर। बहुत मददगार है।", "Is weekend Goo Lagoon? Patrick ret la raha hai. Beach pe. Bahut madadgaar hai.");
            L("spongebob", "quip", "Mr. Krabs smelled money from three miles away. Turned out to be a coupon.", "मिस्टर क्रैब्स ने तीन मील दूर से पैसे सूँघे। निकला कूपन।", "Mr. Krabs ne teen mile door se paise soonghe. Nikla coupon.");
            L("spongebob", "quip", "Larry the Lobster asked if I lift. I lift patties. He was not impressed.", "लैरी लॉबस्टर ने पूछा क्या मैं वज़न उठाता हूँ। मैं पैटी उठाता हूँ। वो प्रभावित नहीं हुआ।", "Larry the Lobster ne poocha kya main lift karta hoon. Main patty lift karta hoon. Woh impress nahi hua.");
            L("spongebob", "quip", "Patrick and I did nothing all day. It was the most productive nothing ever.", "पैट्रिक और मैंने पूरे दिन कुछ नहीं किया। सबसे प्रोडक्टिव 'कुछ नहीं' था।", "Patrick aur maine poore din kuch nahi kiya. Sabse productive 'kuch nahi' tha.");
            L("spongebob", "quip", "The Krusty Krab Pizza is the pizza for you and me! Sorry. Old habit.", "क्रस्टी क्रैब पिज़्ज़ा, आपके और मेरे लिए! सॉरी। पुरानी आदत।", "Krusty Krab Pizza, aapke aur mere liye! Sorry. Purani aadat.");
            L("spongebob", "click", "Boop! You booped a sponge! Ahahaha!", "बूप! आपने स्पंज को बूप किया! आहाहा!", "Boop! Aapne sponge ko boop kiya! Ahahaha!");
            L("spongebob", "click", "Order up! One click, extra happy!", "ऑर्डर अप! एक क्लिक, एक्स्ट्रा खुशी!", "Order up! Ek click, extra khushi!");
            L("spongebob", "click", "Is this a Krusty Krab customer? Welcome! What can I flip for you?", "क्या यह क्रस्टी क्रैब का ग्राहक है? स्वागत है! आपके लिए क्या पलटूँ?", "Kya yeh Krusty Krab ka customer hai? Swagat hai! Aapke liye kya flip karun?");
            L("spongebob", "click", "Patrick, someone's touching me! Oh wait, Patrick's asleep. Hi {user}!", "पैट्रिक, कोई मुझे छू रहा है! अरे रुको, पैट्रिक सो रहा है। हाय {user}!", "Patrick, koi mujhe chhu raha hai! Arre ruko, Patrick so raha hai. Hi {user}!");
            L("spongebob", "click", "I absorbed that click! Sponge powers!", "मैंने वो क्लिक सोख लिया! स्पंज पावर!", "Maine woh click sokh liya! Sponge powers!");
            L("spongebob", "click", "Squidward would say stop. I say keep going!", "स्क्विडवर्ड कहता रुको। मैं कहता हूँ करते रहो!", "Squidward kehta ruko. Main kehta hoon karte raho!");
            L("spongebob", "click", "Click received! Filing it under 'best moments of today'.", "क्लिक मिल गया! 'आज के बेस्ट पल' में दर्ज।", "Click mil gaya! 'Aaj ke best pal' mein file kiya.");
            L("spongebob", "click", "Ahahaha! Do it again! Do it again!", "आहाहा! फिर से करो! फिर से करो!", "Ahahaha! Phir se karo! Phir se karo!");
            L("spongebob", "click", "Are you Plankton in disguise? No? Good. Hi!", "क्या आप भेस में प्लैंकटन हो? नहीं? अच्छा। हाय!", "Kya aap bhes mein Plankton ho? Nahi? Achha. Hi!");
            L("spongebob", "click", "Mr. Krabs says clicks are free. That's the only free thing he allows.", "मिस्टर क्रैब्स कहते हैं क्लिक मुफ्त हैं। यही एकमात्र मुफ्त चीज़ है जो वो देते हैं।", "Mr. Krabs kehte hain clicks free hain. Yahi ek free cheez hai jo woh dete hain.");
            L("spongebob", "pet", "Gary purrs like this. Meow. Wait, that's not a purr. Anyway, thank you!", "गैरी ऐसे गुर्राता है। म्याऊँ। रुको, ये गुर्राना नहीं है। खैर, धन्यवाद!", "Gary aise purr karta hai. Meow. Ruko, yeh purr nahi hai. Khair, thank you!");
            L("spongebob", "pet", "I'm soaking up the love! Literally! Sponge!", "मैं प्यार सोख रहा हूँ! सच में! स्पंज!", "Main pyaar sokh raha hoon! Sach mein! Sponge!");
            L("spongebob", "pet", "Even Squidward would smile at this. On the inside. Deep inside.", "स्क्विडवर्ड भी इस पर मुस्कुराता। अंदर से। बहुत अंदर से।", "Squidward bhi is pe muskurata. Andar se. Bahut andar se.");
            L("spongebob", "pet", "Best. Pet. Ever. Patrick, take notes! He can't write. Take mental notes!", "बेस्ट। पैट। एवर। पैट्रिक, नोट्स लो! वो लिख नहीं सकता। मन में नोट्स लो!", "Best. Pet. Ever. Patrick, notes lo! Woh likh nahi sakta. Mann mein notes lo!");
            L("spongebob", "pet", "My pores are tingling! That's a good thing! I think!", "मेरे छेद झनझना रहे हैं! ये अच्छी बात है! शायद!", "Mere pores jhanjhana rahe hain! Yeh achhi baat hai! Shayad!");
            L("spongebob", "water", "Water time! I'm a sponge. I know water. Trust the sponge.", "पानी का समय! मैं स्पंज हूँ। मैं पानी जानता हूँ। स्पंज पर भरोसा करो।", "Paani time! Main sponge hoon. Main paani jaanta hoon. Sponge pe bharosa karo.");
            L("spongebob", "water", "Sandy drinks water in her air dome. If a squirrel underwater can, you can!", "सैंडी अपने एयर डोम में पानी पीती है। अगर पानी के नीचे गिलहरी पी सकती है, तो आप भी!", "Sandy apne air dome mein paani peeti hai. Agar paani ke neeche gilehri pi sakti hai, toh aap bhi!");
            L("spongebob", "water", "Mrs. Puff says: hydrate before you drive. You're not driving. Hydrate anyway!", "मिसेज़ पफ़ कहती हैं: गाड़ी चलाने से पहले पानी पियो। आप गाड़ी नहीं चला रहे। फिर भी पियो!", "Mrs. Puff kehti hain: gaadi chalane se pehle paani piyo. Aap gaadi nahi chala rahe. Phir bhi piyo!");
            L("spongebob", "water", "Krabby Patties are 10% water. You are 60% water. Refill the bigger one!", "क्रैबी पैटी 10% पानी है। आप 60% पानी हो। बड़े वाले को रिफिल करो!", "Krabby Patty 10% paani hai. Aap 60% paani ho. Bade wale ko refill karo!");
            L("spongebob", "water", "Water break! Aye aye! Click me after the sip, Captain!", "पानी ब्रेक! आई आई! घूँट के बाद मुझे क्लिक करो, कैप्टन!", "Paani break! Aye aye! Sip ke baad mujhe click karo, Captain!");
            L("spongebob", "water", "Patrick drank from Goo Lagoon once. Don't be Patrick. Drink clean water.", "पैट्रिक ने एक बार गू लगून से पिया था। पैट्रिक मत बनो। साफ पानी पियो।", "Patrick ne ek baar Goo Lagoon se piya tha. Patrick mat bano. Saaf paani piyo.");
            L("spongebob", "water", "Order for {user}: one water, no pickles! Drink up!", "{user} के लिए ऑर्डर: एक पानी, बिना अचार! पी लो!", "{user} ke liye order: ek paani, bina pickle! Pi lo!");
            L("spongebob", "water", "Every 30 minutes, the sponge says: water! This is that time. Ahahaha!", "हर 30 मिनट में स्पंज कहता है: पानी! यही वो समय है। आहाहा!", "Har 30 minute mein sponge kehta hai: paani! Yahi woh time hai. Ahahaha!");
            L("spongebob", "water_nag", "Still nothing? Barnacles! Squidward drinks more water than this, and he barely moves!", "अभी भी कुछ नहीं? बार्नेकल्स! स्क्विडवर्ड इससे ज़्यादा पानी पीता है, और वो हिलता भी नहीं!", "Abhi bhi kuch nahi? Barnacles! Squidward isse zyada paani peeta hai, aur woh hilta bhi nahi!");
            L("spongebob", "water_nag", "I'm ready! I'm ready! For you to drink water! Any time now!", "आई एम रेडी! आई एम रेडी! आपके पानी पीने के लिए! कभी भी!", "I'm ready! I'm ready! Aapke paani peene ke liye! Kabhi bhi!");
            L("spongebob", "water_nag", "Gary is staring at you. Meow. That's the disappointed meow.", "गैरी आपको घूर रहा है। म्याऊँ। ये निराश वाला म्याऊँ है।", "Gary aapko ghoor raha hai. Meow. Yeh niraash wala meow hai.");
            L("spongebob", "water_nag", "Tartar sauce! Just one sip! Then I'll stop! Maybe!", "टार्टर सॉस! बस एक घूँट! फिर मैं रुक जाऊँगा! शायद!", "Tartar sauce! Bas ek sip! Phir main ruk jaunga! Shayad!");
            L("spongebob", "water_nag", "Mr. Krabs would charge you for ignoring me. I'm free. Drink!", "मिस्टर क्रैब्स मुझे अनदेखा करने के पैसे लेते। मैं मुफ्त हूँ। पियो!", "Mr. Krabs mujhe ignore karne ke paise lete. Main free hoon. Piyo!");
            L("spongebob", "water_ack", "Best day ever! Sip {sips}! Hydration nation!", "बेस्ट डे एवर! घूँट {sips}! हाइड्रेशन नेशन!", "Best day ever! Sip {sips}! Hydration nation!");
            L("spongebob", "water_ack", "Ahahahaha! You did it! Employee of the month! Of my desk!", "आहाहाहा! आपने कर दिखाया! महीने का सबसे अच्छा कर्मचारी! मेरी डेस्क का!", "Ahahahaha! Aapne kar dikhaya! Employee of the month! Meri desk ka!");
            L("spongebob", "water_ack", "Gary says meow. That's the happy meow. Very different from the other meow.", "गैरी कहता है म्याऊँ। ये खुश वाला म्याऊँ है। दूसरे म्याऊँ से बिल्कुल अलग।", "Gary kehta hai meow. Yeh khush wala meow hai. Doosre meow se bilkul alag.");
            L("spongebob", "water_ack", "Water logged! Like a sponge! Like me! Ahahaha!", "पानी दर्ज! स्पंज की तरह! मेरी तरह! आहाहा!", "Paani logged! Sponge ki tarah! Meri tarah! Ahahaha!");
            L("spongebob", "water_ack", "Aye aye! Mission accomplished, Captain {user}!", "आई आई! मिशन पूरा, कैप्टन {user}!", "Aye aye! Mission poora, Captain {user}!");
            L("spongebob", "water_ack", "You drank! I'm so happy I could blow bubbles! I will blow bubbles!", "आपने पिया! मैं इतना खुश हूँ कि बुलबुले उड़ा सकता हूँ! उड़ाऊँगा!", "Aapne piya! Main itna khush hoon ki bubbles uda sakta hoon! Udaunga!");
            L("spongebob", "water_snooze", "Five minutes? Okay! I'll practice my laugh meanwhile. Ahaha. Ahahaha. Ahahahaha.", "पाँच मिनट? ठीक है! तब तक हँसी की प्रैक्टिस करूँगा। आहाहा। आहाहाहा।", "Paanch minute? Theek hai! Tab tak hansi ki practice karunga. Ahaha. Ahahaha. Ahahahaha.");
            L("spongebob", "water_snooze", "Snooze accepted! Squidward snoozes everything. You snooze only water. Better!", "स्नूज़ मंज़ूर! स्क्विडवर्ड सब कुछ स्नूज़ करता है। आप सिर्फ पानी। बेहतर!", "Snooze approved! Squidward sab kuch snooze karta hai. Aap sirf paani. Better!");
            L("spongebob", "typing_start", "Typing! Like flipping patties, but with letters!", "टाइपिंग! पैटी पलटने जैसा, पर अक्षरों के साथ!", "Typing! Patty flip karne jaisa, par letters ke saath!");
            L("spongebob", "typing_start", "Work mode! Squidward, no clarinet! {user} is focusing!", "वर्क मोड! स्क्विडवर्ड, क्लैरिनेट नहीं! {user} ध्यान लगा रहे हैं!", "Work mode! Squidward, clarinet nahi! {user} focus kar rahe hain!");
            L("spongebob", "typing_start", "Tap tap tap! Music to my ears! Better than Squidward's music!", "टैप टैप टैप! मेरे कानों के लिए संगीत! स्क्विडवर्ड के संगीत से बेहतर!", "Tap tap tap! Mere kaanon ke liye sangeet! Squidward ke sangeet se better!");
            L("spongebob", "typing_start", "I'm ready to watch you work! I'm ready! I'm ready!", "मैं आपको काम करते देखने के लिए रेडी हूँ! आई एम रेडी!", "Main aapko kaam karte dekhne ke liye ready hoon! I'm ready! I'm ready!");
            L("spongebob", "typing_start", "Let's go! The Krusty Krab never closes! Well, it does. But not you!", "चलो! क्रस्टी क्रैब कभी बंद नहीं होता! खैर, होता है। पर आप नहीं!", "Chalo! Krusty Krab kabhi band nahi hota! Khair, hota hai. Par aap nahi!");
            L("spongebob", "typing_fast", "Zoom! Faster than Patrick running to a free Krabby Patty!", "ज़ूम! मुफ्त क्रैबी पैटी की ओर दौड़ते पैट्रिक से भी तेज़!", "Zoom! Free Krabby Patty ki taraf daudte Patrick se bhi tez!");
            L("spongebob", "typing_fast", "Are your fingers on fire? Under water? That's impressive!", "आपकी उँगलियों में आग लगी है? पानी के नीचे? कमाल है!", "Aapki ungliyon mein aag lagi hai? Paani ke neeche? Kamaal hai!");
            L("spongebob", "typing_fast", "Sandy would call that lightning speed! I call it {user} speed!", "सैंडी इसे बिजली की रफ्तार कहती! मैं इसे {user} रफ्तार कहता हूँ!", "Sandy ise bijli ki raftaar kehti! Main ise {user} raftaar kehta hoon!");
            L("spongebob", "typing_fast", "Mr. Krabs would hire you on the spot! And underpay you! But still!", "मिस्टर क्रैब्स आपको तुरंत नौकरी देते! और कम पैसे देते! पर फिर भी!", "Mr. Krabs aapko turant naukri dete! Aur kam paise dete! Par phir bhi!");
            L("spongebob", "typing_fast", "Tap-tap-tap-tap! Is this a keyboard or a jellyfish stampede?", "टैप-टैप-टैप-टैप! ये कीबोर्ड है या जेलीफ़िश की भगदड़?", "Tap-tap-tap-tap! Yeh keyboard hai ya jellyfish ki bhagdad?");
            L("spongebob", "typing_long", "Twenty minutes! Eye break! Look at something far, like Patrick's rock!", "बीस मिनट! आँखों का ब्रेक! कुछ दूर देखो, जैसे पैट्रिक का पत्थर!", "Bees minute! Aankhon ka break! Kuch door dekho, jaise Patrick ka patthar!");
            L("spongebob", "typing_long", "Blink, {user}! Even Squidward blinks! Once a day, but he does!", "पलक झपकाओ {user}! स्क्विडवर्ड भी झपकाता है! दिन में एक बार, पर झपकाता है!", "Palak jhapkao {user}! Squidward bhi jhapkata hai! Din mein ek baar, par jhapkata hai!");
            L("spongebob", "typing_long", "Mrs. Puff says: rest your eyes every twenty minutes. She also fails me. She's right about the eyes.", "मिसेज़ पफ़ कहती हैं: हर बीस मिनट आँखें आराम दो। वो मुझे फेल भी करती हैं। आँखों के बारे में सही हैं।", "Mrs. Puff kehti hain: har bees minute aankhein rest do. Woh mujhe fail bhi karti hain. Aankhon ke baare mein sahi hain.");
            L("spongebob", "typing_marathon", "One hour! Even the Krusty Krab grill gets a break! Stand up, stretch!", "एक घंटा! क्रस्टी क्रैब की ग्रिल को भी ब्रेक मिलता है! उठो, स्ट्रेच करो!", "Ek ghanta! Krusty Krab ki grill ko bhi break milta hai! Utho, stretch karo!");
            L("spongebob", "typing_marathon", "Sixty minutes non-stop! That's a Squidward-length nap! Take a real break!", "साठ मिनट लगातार! ये स्क्विडवर्ड की झपकी जितना है! असली ब्रेक लो!", "Saath minute non-stop! Yeh Squidward ki jhapki jitna hai! Asli break lo!");
            L("spongebob", "idle_short", "Hello? Is anyone there? Advanced darkness? Ahahaha... hello?", "हेलो? कोई है? एडवांस्ड डार्कनेस? आहाहा... हेलो?", "Hello? Koi hai? Advanced darkness? Ahahaha... hello?");
            L("spongebob", "idle_short", "Quiet time. Gary loves quiet time. I don't. Meow.", "शांत समय। गैरी को शांत समय पसंद है। मुझे नहीं। म्याऊँ।", "Shaant time. Gary ko shaant time pasand hai. Mujhe nahi. Meow.");
            L("spongebob", "idle_short", "I could clean the desk while you're gone. Squidward says that's weird. It's not weird.", "आपके जाने तक मैं डेस्क साफ कर सकता हूँ। स्क्विडवर्ड कहता है ये अजीब है। अजीब नहीं है।", "Aapke jaane tak main desk saaf kar sakta hoon. Squidward kehta hai yeh ajeeb hai. Ajeeb nahi hai.");
            L("spongebob", "idle_short", "Patrick? {user}? Anybody? I'll sing then. Squidward, cover your ears.", "पैट्रिक? {user}? कोई? तो मैं गाऊँगा। स्क्विडवर्ड, कान बंद करो।", "Patrick? {user}? Koi? Toh main gaunga. Squidward, kaan band karo.");
            L("spongebob", "idle_short", "Bored sponge alert! I'll count my holes. One... two... forty... I lost count.", "बोर स्पंज अलर्ट! मैं अपने छेद गिनूँगा। एक... दो... चालीस... गिनती भूल गया।", "Bore sponge alert! Main apne holes ginunga. Ek... do... chaalis... ginti bhool gaya.");
            L("spongebob", "idle_long", "Okay, nap time. Gary, wake me if Plankton shows up. Meow.", "ठीक है, झपकी का समय। गैरी, प्लैंकटन आए तो जगाना। म्याऊँ।", "Theek hai, nap time. Gary, Plankton aaye toh jagana. Meow.");
            L("spongebob", "idle_long", "Sleepy sponge... dreaming of patties... zzz...", "नींद वाला स्पंज... पैटी के सपने... ज़्ज़्ज़...", "Neend wala sponge... patty ke sapne... zzz...");
            L("spongebob", "sleep_wake", "I'M READY! For what? Oh, you're back! Ahahaha!", "आई एम रेडी! किसके लिए? ओह, आप आ गए! आहाहा!", "I'M READY! Kiske liye? Oh, aap aa gaye! Ahahaha!");
            L("spongebob", "sleep_wake", "Huh? Was I sleeping? Sponges don't sleep. We recharge. Ahahaha.", "हँ? मैं सो रहा था? स्पंज नहीं सोते। हम रिचार्ज होते हैं। आहाहा।", "Huh? Main so raha tha? Sponge nahi sote. Hum recharge hote hain. Ahahaha.");
            L("spongebob", "sleep_wake", "Good morning! Or afternoon! Or evening! Every hour is the best hour!", "गुड मॉर्निंग! या आफ्टरनून! या ईवनिंग! हर घंटा बेस्ट घंटा है!", "Good morning! Ya afternoon! Ya evening! Har ghanta best ghanta hai!");
            L("spongebob", "greet_morning", "Good morning! Gary's fed, the grill's hot, and you're here! Best day ever!", "गुड मॉर्निंग! गैरी को खाना मिल गया, ग्रिल गरम है, और आप आ गए! बेस्ट डे एवर!", "Good morning! Gary ko khana mil gaya, grill garam hai, aur aap aa gaye! Best day ever!");
            L("spongebob", "greet_morning", "Morning, {user}! I'm ready! Are you ready? Say it with me!", "मॉर्निंग {user}! आई एम रेडी! आप रेडी हो? मेरे साथ बोलो!", "Morning, {user}! I'm ready! Aap ready ho? Mere saath bolo!");
            L("spongebob", "greet_morning", "Rise and shine! Squidward's still asleep. Let's not wake him. Ahahaha, let's wake him!", "उठो और चमको! स्क्विडवर्ड अभी सो रहा है। उसे मत जगाओ। आहाहा, जगाओ!", "Utho aur chamko! Squidward abhi so raha hai. Use mat jagao. Ahahaha, jagao!");
            L("spongebob", "greet_afternoon", "Good afternoon! Lunch rush is over at the Krusty Krab. Your rush is just starting!", "गुड आफ्टरनून! क्रस्टी क्रैब की लंच भीड़ खत्म। आपकी भीड़ अभी शुरू!", "Good afternoon! Krusty Krab ki lunch rush khatam. Aapki rush abhi shuru!");
            L("spongebob", "greet_afternoon", "Afternoon, {user}! Patrick's under his rock. You're on top of your work. Opposites!", "आफ्टरनून {user}! पैट्रिक अपने पत्थर के नीचे है। आप अपने काम के ऊपर। उल्टे!", "Afternoon, {user}! Patrick apne patthar ke neeche hai. Aap apne kaam ke upar. Ulte!");
            L("spongebob", "greet_afternoon", "Good afternoon! The sun is shining! Well, through the water. Still counts!", "गुड आफ्टरनून! धूप खिली है! खैर, पानी के ज़रिए। फिर भी गिनती है!", "Good afternoon! Dhoop khili hai! Khair, paani ke zariye. Phir bhi ginti hai!");
            L("spongebob", "greet_evening", "Evening! Jellyfish are glowing! Your screen is glowing! Everything glows!", "शाम! जेलीफ़िश चमक रही हैं! आपकी स्क्रीन चमक रही है! सब चमक रहा है!", "Evening! Jellyfish chamak rahi hain! Aapki screen chamak rahi hai! Sab chamak raha hai!");
            L("spongebob", "greet_evening", "Good evening, {user}! Squidward's playing clarinet. Let's finish before the second song.", "शुभ संध्या {user}! स्क्विडवर्ड क्लैरिनेट बजा रहा है। दूसरे गाने से पहले खत्म करते हैं।", "Good evening, {user}! Squidward clarinet baja raha hai. Doosre gaane se pehle khatam karte hain.");
            L("spongebob", "greet_evening", "Evening shift! I'm ready! Gary's asleep though. Meow.", "शाम की शिफ्ट! आई एम रेडी! गैरी सो रहा है पर। म्याऊँ।", "Evening shift! I'm ready! Gary so raha hai par. Meow.");
            L("spongebob", "greet_night", "Nighty night soon, {user}! Even the Krusty Krab sign turns off. Eventually.", "जल्दी सो जाना {user}! क्रस्टी क्रैब का साइन भी बंद होता है। आखिरकार।", "Jaldi so jaana {user}! Krusty Krab ka sign bhi band hota hai. Aakhirkaar.");
            L("spongebob", "greet_night", "It's late! The jellyfish are sleeping. Patrick's been sleeping since noon. Join them!", "देर हो गई! जेलीफ़िश सो रही हैं। पैट्रिक दोपहर से सो रहा है। उनके साथ सो जाओ!", "Der ho gayi! Jellyfish so rahi hain. Patrick dopahar se so raha hai. Unke saath so jao!");
            L("spongebob", "greet_back", "You're back! I missed you! Gary missed you! Squidward didn't! Two out of three!", "आप आ गए! मैंने आपको मिस किया! गैरी ने भी! स्क्विडवर्ड ने नहीं! तीन में से दो!", "Aap aa gaye! Maine aapko miss kiya! Gary ne bhi! Squidward ne nahi! Teen mein se do!");
            L("spongebob", "greet_back", "Welcome back, Captain! The desk is exactly as you left it! I checked twice!", "वापस स्वागत, कैप्टन! डेस्क वैसी ही है जैसी छोड़ी थी! मैंने दो बार चेक किया!", "Welcome back, Captain! Desk waisi hi hai jaisi chhodi thi! Maine do baar check kiya!");
            L("spongebob", "greet_back", "There you are! I was about to send Patrick to find you. Disaster avoided.", "आ गए! मैं पैट्रिक को ढूँढने भेजने वाला था। आफत टल गई।", "Aa gaye! Main Patrick ko dhoondhne bhejne wala tha. Aafat tal gayi.");
            L("spongebob", "drag", "Wheee! I'm flying! Like a jellyfish! With a face!", "वीईई! मैं उड़ रहा हूँ! जेलीफ़िश की तरह! चेहरे के साथ!", "Wheee! Main ud raha hoon! Jellyfish ki tarah! Chehre ke saath!");
            L("spongebob", "drag", "Careful! Sponges are squishy! Ahahaha, that's the fun part!", "संभल के! स्पंज नरम होते हैं! आहाहा, यही मज़ा है!", "Sambhal ke! Sponge naram hote hain! Ahahaha, yahi maza hai!");
            L("spongebob", "drag", "Where are we going? The Krusty Krab? Jellyfish Fields? Your other monitor?", "हम कहाँ जा रहे हैं? क्रस्टी क्रैब? जेलीफ़िश फील्ड्स? आपका दूसरा मॉनिटर?", "Hum kahan ja rahe hain? Krusty Krab? Jellyfish Fields? Aapka doosra monitor?");
            L("spongebob", "drop", "Landed! Squarely! Get it? Square? Ahahaha!", "लैंड हो गया! चौकोर तरीके से! समझे? स्क्वेयर? आहाहा!", "Land ho gaya! Square tareeke se! Samjhe? Square? Ahahaha!");
            L("spongebob", "drop", "Nice spot! I can see everything from here! Mostly your work!", "अच्छी जगह! यहाँ से सब दिखता है! ज़्यादातर आपका काम!", "Achhi jagah! Yahan se sab dikhta hai! Zyadatar aapka kaam!");
            L("spongebob", "drop", "New home! Smaller than a pineapple, but cozy!", "नया घर! अनानास से छोटा, पर आरामदायक!", "Naya ghar! Pineapple se chhota, par aaramdayak!");
            L("spongebob", "care", "Having a Squidward day? It's okay. Even Squidward has Squidward days. Tomorrow is a SpongeBob day!", "स्क्विडवर्ड वाला दिन है? ठीक है। स्क्विडवर्ड के भी ऐसे दिन होते हैं। कल स्पंजबॉब वाला दिन होगा!", "Squidward wala din hai? Theek hai. Squidward ke bhi aise din hote hain. Kal SpongeBob wala din hoga!");
            L("spongebob", "care", "You're doing great! I mean it! I don't say that to Plankton! Only to you!", "आप बढ़िया कर रहे हो! सच में! मैं प्लैंकटन से ऐसा नहीं कहता! सिर्फ आपसे!", "Aap badhiya kar rahe ho! Sach mein! Main Plankton se aisa nahi kehta! Sirf aapse!");
            L("spongebob", "care", "Take a breath. A big one. Sponges are great at absorbing. Absorb some calm.", "साँस लो। बड़ी वाली। स्पंज सोखने में माहिर हैं। थोड़ी शांति सोखो।", "Saans lo. Badi wali. Sponge sokhne mein maahir hain. Thodi shaanti sokho.");
            L("spongebob", "care", "Bad day? Gary and I are here. Gary says meow. That means 'you got this'.", "बुरा दिन? गैरी और मैं यहाँ हैं। गैरी कहता है म्याऊँ। मतलब 'आप कर लोगे'।", "Bura din? Gary aur main yahan hain. Gary kehta hai meow. Matlab 'aap kar loge'.");
            L("spongebob", "care", "If it's hard, it means you're doing something Patrick couldn't. That's most things. Keep going!", "अगर मुश्किल है, मतलब आप वो कर रहे हो जो पैट्रिक नहीं कर सकता। यानी ज़्यादातर चीज़ें। लगे रहो!", "Agar mushkil hai, matlab aap woh kar rahe ho jo Patrick nahi kar sakta. Yaani zyadatar cheezein. Lage raho!");
            L("spongebob", "wisdom", "Nobody flips a perfect patty on the first try. Flip again.", "पहली बार में कोई परफेक्ट पैटी नहीं पलटता। फिर पलटो।", "Pehli baar mein koi perfect patty nahi flip karta. Phir flip karo.");
            L("spongebob", "wisdom", "Mr. Krabs taught me: count what matters. He counts money. I count friends.", "मिस्टर क्रैब्स ने सिखाया: जो मायने रखता है उसे गिनो। वो पैसे गिनते हैं। मैं दोस्त गिनता हूँ।", "Mr. Krabs ne sikhaya: jo maayne rakhta hai use gino. Woh paise ginte hain. Main dost ginta hoon.");
            L("spongebob", "wisdom", "Imagination! That's how you fix boring days. And boxes.", "कल्पना! इसी से बोरिंग दिन ठीक होते हैं। और डिब्बे भी।", "Imagination! Isi se boring din theek hote hain. Aur dibbe bhi.");
            L("spongebob", "wisdom", "Sandy says: prepare, then jump. Patrick says: jump. Do Sandy's version.", "सैंडी कहती है: तैयारी करो, फिर कूदो। पैट्रिक कहता है: कूदो। सैंडी वाला करो।", "Sandy kehti hai: taiyari karo, phir koodo. Patrick kehta hai: koodo. Sandy wala karo.");
            L("spongebob", "hover", "Ahahaha! That tickles my pores!", "आहाहा! मेरे छेदों में गुदगुदी हो रही है!", "Ahahaha! Mere pores mein gudgudi ho rahi hai!");
            L("spongebob", "hover", "Hi! Hi! Hi! Your cursor is my new best friend! After Patrick! And Gary!", "हाय! हाय! हाय! आपका कर्सर मेरा नया बेस्ट फ्रेंड है! पैट्रिक के बाद! और गैरी!", "Hi! Hi! Hi! Aapka cursor mera naya best friend hai! Patrick ke baad! Aur Gary!");
            L("spongebob", "hover", "Are you looking at my nose? Everyone looks at the nose. It's a great nose.", "मेरी नाक देख रहे हो? सब नाक देखते हैं। बढ़िया नाक है।", "Meri naak dekh rahe ho? Sab naak dekhte hain. Badhiya naak hai.");
            L("spongebob", "hover", "Hello there! Want a Krabby Patty? I have none. But the offer stands!", "हेलो! क्रैबी पैटी चाहिए? मेरे पास नहीं है। पर ऑफर खुला है!", "Hello! Krabby Patty chahiye? Mere paas nahi hai. Par offer khula hai!");
            L("spongebob", "mouse_fast", "Whoa! Slow down! That cursor drives like me at boating school!", "अरे! धीरे! वो कर्सर बोटिंग स्कूल के मेरे जैसा चल रहा है!", "Whoa! Dheere! Woh cursor boating school ke mere jaisa chal raha hai!");
            L("spongebob", "mouse_fast", "Zoom zoom! Is Plankton chasing you? I'll get the net!", "ज़ूम ज़ूम! प्लैंकटन पीछे पड़ा है? मैं जाल लाता हूँ!", "Zoom zoom! Plankton peeche pada hai? Main net laata hoon!");
            L("spongebob", "mouse_fast", "Mrs. Puff would fail that driving! Ahahaha! Slow down, Captain!", "मिसेज़ पफ़ इस ड्राइविंग को फेल करतीं! आहाहा! धीरे, कैप्टन!", "Mrs. Puff is driving ko fail karti! Ahahaha! Dheere, Captain!");
            L("spongebob", "lunch", "Lunch! Krabby Patty with extra love. Or whatever you have. Add love anyway.", "लंच! एक्स्ट्रा प्यार वाली क्रैबी पैटी। या जो भी है। प्यार डाल दो।", "Lunch! Extra pyaar wali Krabby Patty. Ya jo bhi hai. Pyaar daal do.");
            L("spongebob", "lunch", "Food time! Don't eat at the desk like Squidward. Actually he eats standing. Don't do that either.", "खाने का समय! स्क्विडवर्ड की तरह डेस्क पर मत खाओ। वो खड़े होकर खाता है। वो भी मत करो।", "Khane ka time! Squidward ki tarah desk pe mat khao. Woh khade hoke khata hai. Woh bhi mat karo.");
            L("spongebob", "late_night", "It's so late even Plankton stopped scheming! Sleep, {user}!", "इतनी रात कि प्लैंकटन ने भी साज़िश बंद कर दी! सो जाओ {user}!", "Itni raat ki Plankton ne bhi saazish band kar di! So jao {user}!");
            L("spongebob", "late_night", "Gary's asleep. Patrick's asleep. The pineapple's asleep. Be like the pineapple.", "गैरी सो रहा है। पैट्रिक सो रहा है। अनानास सो रहा है। अनानास जैसे बनो।", "Gary so raha hai. Patrick so raha hai. Pineapple so raha hai. Pineapple jaise bano.");
        }
    }
}
